INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46611, 'Joshua 17:14', 'Joshua', 17, 14, 'یوه ورځ د یوسف اولاده یوشع ته ورغله او پوښتنه یې ترې وکړه: «تا ولې مونږ ته د دې ځمکې څخه یوازې یوه برخه راکړې ده؟ څښتن مونږ ته تل برکت راکړی دی، په دې خاطر زمونږ خلک ډېر زیات دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_14.mp3', '', 1761754199, 1761754199),
(46612, 'Joshua 17:15', 'Joshua', 17, 15, 'یوشع په ځواب کې وویل: «که چېرې تاسو ډېر یئ او د افرایم غرنۍ سیمه ستاسو دپاره ډېره کمه وي، بیا پورته ځنګلونو ته لاړ شئ او د فرزیانو او رفاییانو په ځمکه کې د ځانونو دپاره ځمکه د ونو څخه پاکه کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_15.mp3', '', 1761754199, 1761754199),
(46613, 'Joshua 17:16', 'Joshua', 17, 16, 'د یوسف اولادې په ځواب کې وویل: «زمونږ دپاره غرنۍ سیمه بس نه ده. برسېره پردې، ټول کنعانیان چې په ډاګونو کې یعنې هغوی چې په بیت شان او د هغه ځای په شاوخوا کلیو کې اوسیږي او هغه کنعانیان چې د یزرعیل په دره کې اوسیږي، هغوی ټول د اوسپنې جنګي ګاډۍ لري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_16.mp3', '', 1761754199, 1761754199),
(46614, 'Joshua 17:17', 'Joshua', 17, 17, 'یوشع د افرایم او د لوېدیځې منسي قبیلو ته وویل: «تاسو په رښتیا سره زیات او ډېر قوي یئ. تاسو ته به د یوې برخې څخه زیاته سیمه درکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_17.mp3', '', 1761754199, 1761754199),
(46615, 'Joshua 17:18', 'Joshua', 17, 18, 'غرنۍ سیمه به ستاسو شي. خو هغه ځمکه یو ځنګل دی، تاسو باید ونې ووهئ او ځمکه یې پاکه کړئ او هغه په پوره توګه ونیسئ. که څه هم کنعانیان قوي دي او د اوسپنې جنګي ګاډۍ لري، خو تاسو به وکولای شئ چې هغوی وشړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua17_verse_18.mp3', '', 1761754199, 1761754199),
(46616, 'Psalms 74:1', 'Psalms', 74, 1, 'خدایه ولې دې رد کړي یو د تل دپاره؟ ستا قهر ولې لکه اور په شان دی بل په مونږه؟ مونږه خو یو ستا د رمې پسونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_1.mp3', '', 1761754199, 1761754199),
(46617, 'Psalms 74:2', 'Psalms', 74, 2, 'ته در په یاد کړه هغه خپل قوم چې ډېر پخوا نه غوره کړی تا خپل ځان دپاره کوم چې تا وژغوره له غلامۍ نه چې شي ستا غوره قوم در په یاد کړه د صهیون هغه غر چې اوسېدلې په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_2.mp3', '', 1761754199, 1761754199),
(46618, 'Psalms 74:3', 'Psalms', 74, 3, 'واخله قدم دې د تلپاتې کنډوالو په لوري هرڅه چې وو عبادت ځای کې ویجاړ کړي دښمن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_3.mp3', '', 1761754199, 1761754199),
(46619, 'Psalms 74:4', 'Psalms', 74, 4, 'نارې وهلې د بري ستا دښمنانو ستا سپېڅلي کور کې خپل بیرغونه یې ودرولي دي د نښې د بریا په توګه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_4.mp3', '', 1761754199, 1761754199),
(46620, 'Psalms 74:5', 'Psalms', 74, 5, 'دوی ښکارېدل د چوب شکنو په شان چې دوی وهلې ونې په تبرونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_5.mp3', '', 1761754199, 1761754199),
(46621, 'Psalms 74:6', 'Psalms', 74, 6, 'په تبرونو او جبلونو باندې کړل یې خراب ټول د لرګو نقشونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_6.mp3', '', 1761754199, 1761754199),
(46622, 'Psalms 74:7', 'Psalms', 74, 7, 'ستا سپېڅلي کور ته یې اور واچاوه دوی بې‌حرمت کړ هغه ځای چې دی ستا نوم ورپورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_7.mp3', '', 1761754199, 1761754199),
(46623, 'Psalms 74:8', 'Psalms', 74, 8, 'هغوی د ځانه سره داسې ویل: «مونږ به بیخي هغوی له منځه یوسو» سوځول یې په دې خاوره کې ټول د عبادت ځایونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_8.mp3', '', 1761754199, 1761754199),
(46624, 'Psalms 74:9', 'Psalms', 74, 9, 'مونږه نور ونه لیدلې ستا معجزې پیغمبرانو نه څوک پاتې نه شو څوک نه پوهیږي دا حالت به کړي دوام تر کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_9.mp3', '', 1761754199, 1761754199),
(46625, 'Psalms 74:10', 'Psalms', 74, 10, 'ترڅو به ستا دښمنان تاته خدایه پېغورونه کوي؟ بې‌حرمتي به تر ابده پورې ستا د نامه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_10.mp3', '', 1761754199, 1761754199),
(46626, 'Psalms 74:11', 'Psalms', 74, 11, 'ولې دې مونږ ته خپل ښي لاس رانه کړ؟ وښایه ځواک دې خپل او دوی نابود کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_11.mp3', '', 1761754199, 1761754199),
(46627, 'Psalms 74:12', 'Psalms', 74, 12, 'خو له اوله ته پاچا یې زما ای خدایه او تا راوړی دی خلاصون ځمکې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_12.mp3', '', 1761754199, 1761754199),
(46628, 'Psalms 74:13', 'Psalms', 74, 13, 'په خپل قوت سره جدا دې کړې اوبه د دریاب او په اوبو کې دې کړل مات د بلاګانو تندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_13.mp3', '', 1761754199, 1761754199),
(46629, 'Psalms 74:14', 'Psalms', 74, 14, 'وې همدا ته چې د بحري بلا دې سرونه مات کړل تا په جسد د دې ماړه کړل ځناور د دښتې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_14.mp3', '', 1761754199, 1761754199),
(46630, 'Psalms 74:15', 'Psalms', 74, 15, 'تا جاري کړلې چینې او هم خوړونه د تل دپاره دې کړل وچ سیندونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_15.mp3', '', 1761754199, 1761754199),
(46631, 'Psalms 74:16', 'Psalms', 74, 16, 'شپه او ورځ دواړه ستا دي تا ځای په ځای لمر او سپوږمۍ کړل خپلو ځایونو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_16.mp3', '', 1761754199, 1761754199),
(46632, 'Psalms 74:17', 'Psalms', 74, 17, 'تا سرحدونه وټاکل د ځمکې تا اوړی ژمی جوړ کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_17.mp3', '', 1761754199, 1761754199),
(46633, 'Psalms 74:18', 'Psalms', 74, 18, 'خو ای څښتنه دا په یاد ساته چې دښمنان دې کړي خندا تا پورې او کم‌عقل خلک سپکاوی کړي تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_18.mp3', '', 1761754199, 1761754199),
(46634, 'Psalms 74:19', 'Psalms', 74, 19, 'د خپل بې‌وزله قوم ژوند مه هېروه تل دپاره د بېچاره کوترې ژوند دې ځناورو لره مه پرېږده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_19.mp3', '', 1761754199, 1761754199),
(46635, 'Psalms 74:20', 'Psalms', 74, 20, 'تا چې کوم لوظ کړی ؤ مونږ سره در یاد کړه هغه ځکه چې ډک دی هر تیاره ځای د دنیا له ظلمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_20.mp3', '', 1761754199, 1761754199),
(46636, 'Psalms 74:21', 'Psalms', 74, 21, 'مظلومان مه پرېږده چې وشرمیږي پرېږده چې دغه غریبان او محتاج خلک دې ستاینه ستا د نوم وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_21.mp3', '', 1761754199, 1761754199),
(46637, 'Psalms 74:22', 'Psalms', 74, 22, 'خدایه، راپورته شه دفاع وکړه له خپله ځانه دا یاد ساته چې کم‌عقلان ټوله ورځ تا پورې خندا کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_22.mp3', '', 1761754199, 1761754199),
(46638, 'Psalms 74:23', 'Psalms', 74, 23, 'ته دې د خپلو مخالفینو قهرجنې چیغې مه هېروه دا دوامداره شورماشور چې دښمنانو دی جوړ کړی ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms74_verse_23.mp3', '', 1761754199, 1761754199),
(46639, 'Joshua 20:1', 'Joshua', 20, 1, 'بیا څښتن یوشع ته وویل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_1.mp3', '', 1761754199, 1761754199),
(46640, 'Joshua 20:2', 'Joshua', 20, 2, 'چې د اسراییلو قوم ته ووایه: «د پناه اخیستلو ښارونه چې د هغو په اړه مې د موسی په وسیله تاسو ته ویلي وو، وټاکئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_2.mp3', '', 1761754199, 1761754199),
(46641, 'Joshua 20:3', 'Joshua', 20, 3, 'نو هرڅوک چې په سهوې سره یو سړی ووژني، کولای شي هلته لاړ شي او د وژل شوي کس د خپلوانو څخه وتښتي او خوندي پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_3.mp3', '', 1761754199, 1761754199),
(46642, 'Joshua 20:4', 'Joshua', 20, 4, 'هغه کولای شي د دې ښارونو د جملې څخه یو ښار ته وتښتي، د ښار دروازې ته چې د قضاوت ځای دی ورشي او مشرانو ته دې د پېښې په هکله بیان ورکړي. بیا به هغوی هغه کس ته اجازه ورکړي چې ښار ته ورننوځي او هغه ته د اوسېدلو دپاره ځای ورکړي، ترڅو وکولای شي هلته پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_4.mp3', '', 1761754199, 1761754199),
(46643, 'Joshua 20:5', 'Joshua', 20, 5, 'که چېرې بدل اخیستونکی هغه تعقیب کړي، نو د هغه ښار خلک باید په قتل باندې تورن کس هغه ته په لاس ورنه کړي. هغوی باید د هغه ساتنه وکړي، ځکه چې هغه کس یې په سهوې سره وژلی دی او مخکې یې ورسره کومه دښمني نه درلودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_5.mp3', '', 1761754199, 1761754199),
(46644, 'Joshua 20:6', 'Joshua', 20, 6, 'هغه به په دې ښار کې تر هغه وخته پورې پاتې کیږي، ترڅو په علني محاکمه کې بې ګناه ثابت شي او تر هغې پورې چې لوی کاهن مړ شي. بیا هغه کولای شي چې بېرته خپل کور او خپل ښارګوټي ته یعنې د کوم ځای څخه چې هغه راتښتېدلی وي، لاړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_6.mp3', '', 1761754199, 1761754199),
(46645, 'Joshua 20:7', 'Joshua', 20, 7, 'نو د اسراییلو قوم د جلیل قادش چې د نفتالي په غرنۍ سیمه کې ؤ بېل کړ، شکیم یې د افرایم په غرنۍ سیمه کې او قریت اربع (حبرون) یې د یهودا په غرنۍ سیمه کې بېل کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_7.mp3', '', 1761754199, 1761754199),
(46646, 'Joshua 20:8', 'Joshua', 20, 8, 'د اردن د سیند په ختیځ کې د دښتې په لوړه جلګه باندې چې د اریحا ختیځې خواته وه هغوی باصر وټاکه چې د روبین په سیمه کې ؤ، راموت یې په جلعاد کې چې د جاد په سیمه کې پروت ؤ، وټاکه او جولان یې په باشان کې چې د منسي په سیمه کې پروت ؤ، وټاکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_8.mp3', '', 1761754199, 1761754199),
(46647, 'Joshua 20:9', 'Joshua', 20, 9, 'دا د پناه اخیستلو هغه ښارونه وو چې د اسراییلو د ټول قوم دپاره او د هغو پردیو خلکو دپاره چې د هغوی په منځ کې اوسېدل، وټاکل شول. هرچا چې به په سهوې سره بل کس واژه، هغه به د بدل اخیستونکي څخه هلته ساتنه تر لاسه کولای شوه. که چېرې هغه کس اول د غونډې په مخکې نه ؤ ملامت شوی، نو هغه یې نه شو وژلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua20_verse_9.mp3', '', 1761754199, 1761754199),
(46648, 'Psalms 43:1', 'Psalms', 43, 1, 'بې‌ګناهي مې کړه ښکاره، خدایه بې‌دینه خلکو مقابل کې مې دفاع وکړه ته له دروغجنو او بدکارو خلکو خلاص مې کړه ته!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms43_verse_1.mp3', '', 1761754199, 1761754199),
(46649, 'Psalms 43:2', 'Psalms', 43, 2, 'ته ساتونکی یې زما زه دې ولې یم پرې ایښی؟ د خپل دښمن له ظلمه ولې زه ویر کې یمه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms43_verse_2.mp3', '', 1761754199, 1761754199),
(46650, 'Psalms 43:3', 'Psalms', 43, 3, 'راواستوه راته خپل نور او حقیقت چې راته لار وښایي چې مې دوی راولي صهیون ته ستا سپېڅلي غره ته او ستا خپل کور ته چې اوسېږې په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms43_verse_3.mp3', '', 1761754199, 1761754199),
(46651, 'Psalms 43:4', 'Psalms', 43, 4, 'زه به بیا ورشم د خدای د قربانۍ ځای ته د هغه خدای چې یم خوشحاله ترې زه زه غږومه به رباب او ستا ثنا به وایم خدایه، زما خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms43_verse_4.mp3', '', 1761754199, 1761754199),
(46652, 'Psalms 43:5', 'Psalms', 43, 5, 'ای زما ځانه، دومره خفه ولې یم؟ دومره پرېشان ولې یم؟ باید په خدای باندې توکل ولرم یوځلې بیا به یې ثنا ووایم ای زما خدایه، خلاصوونکیه زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms43_verse_5.mp3', '', 1761754199, 1761754199),
(46653, 'Deuteronomy 34:1', 'Deuteronomy', 34, 1, 'موسی د موآب د ډاګونو څخه د نبو غره ته وخوت، یعنې د پیسګاه د غره سرته چې د اریحا په ختیځ کې دی. هلته ورته څښتن ټوله خاوره یعنې د جلعاد سیمه د دان تر ښاره پورې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_1.mp3', '', 1761754199, 1761754199),
(46654, 'Deuteronomy 34:2', 'Deuteronomy', 34, 2, 'د نفتالي ټوله سیمه، د افرایم او منسي سیمې، د مدیترانې تر بحیرې پورې د یهودا ټوله سیمه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_2.mp3', '', 1761754199, 1761754199),
(46655, 'Deuteronomy 34:3', 'Deuteronomy', 34, 3, 'د یهودا جنوبي برخه او هغه ډاګ وروښود چې د صوغر څخه تر اریحا پورې چې د خرما د ونو ښار دی، رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_3.mp3', '', 1761754199, 1761754199),
(46656, 'Deuteronomy 34:4', 'Deuteronomy', 34, 4, 'بیا څښتن موسی ته وویل: «دا هغه خاوره ده چې ما د ابراهیم، اسحاق او یعقوب سره وعده کړې وه چې د هغوی اولادې ته به یې ورکړم. ما ته پرېښودلې چې هغه ووینې، خو ته به د اردن د سیند څخه تېر نه شې او هلته به ورننه نه وځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_4.mp3', '', 1761754199, 1761754199),
(46657, 'Deuteronomy 34:5', 'Deuteronomy', 34, 5, 'نو لکه څنګه چې څښتن ویلي وو، د څښتن خدمتګار موسی هلته د موآب په خاوره کې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_5.mp3', '', 1761754199, 1761754199),
(46658, 'Deuteronomy 34:6', 'Deuteronomy', 34, 6, 'هغه د موآب په هغې دره کې ښخ کړای شو چې د بیت فغور ښار ته مخامخ وه. خو تر نن ورځې پورې هېڅوک نه پوهیږي چې موسی چېرته ښخ شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_6.mp3', '', 1761754199, 1761754199),
(46659, 'Deuteronomy 34:7', 'Deuteronomy', 34, 7, 'موسی یوسلو شل کلن ؤ چې مړ شو، د هغه بدن لا قوي ؤ او د سترګو نظر یې هم ښه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_7.mp3', '', 1761754199, 1761754199),
(46660, 'Deuteronomy 34:8', 'Deuteronomy', 34, 8, 'د اسراییلو قوم د موآب په ډاګونو کې دېرش ورځې د هغه دپاره وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_8.mp3', '', 1761754199, 1761754199),
(46661, 'Deuteronomy 34:9', 'Deuteronomy', 34, 9, 'موسی د خپل مرګ څخه مخکې د نون د زوی یوشع په سر باندې خپل لاسونه کېښودل او هغه یې د خپل ځان په ځای وټاکه. څښتن هغه د حکمت څخه ډک کړ. د اسراییلو قوم د یوشع اطاعت کاوه او په هغو حکمونو باندې یې عمل کاوه چې څښتن هغوی ته د موسی په وسیله ورکړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_9.mp3', '', 1761754199, 1761754199),
(46662, 'Deuteronomy 34:10', 'Deuteronomy', 34, 10, 'په اسراییلو کې هېڅکله د موسی په شان پیغمبر نه دی پیدا شوی. څښتن د هغه سره مخامخ خبرې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_10.mp3', '', 1761754199, 1761754199),
(46663, 'Deuteronomy 34:11', 'Deuteronomy', 34, 11, 'بل هېڅ پیغمبر داسې لویې معجزې نه دي ښودلې لکه څنګه چې څښتن موسی رالېږلی ؤ چې د فرعون، د هغه د درباریانو او د مصر د ټولو خلکو په حضور کې یې وښایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_11.mp3', '', 1761754199, 1761754199),
(46664, 'Deuteronomy 34:12', 'Deuteronomy', 34, 12, 'بل هېڅ پیغمبر داسې قدرت نه درلود چې هغه لوی او وېروونکي کارونه وکړي چې موسی د ټولو اسراییلیانو په مخکې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy34_verse_12.mp3', '', 1761754199, 1761754199),
(46665, 'Jeremiah 16:1', 'Jeremiah', 16, 1, 'د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_1.mp3', '', 1761754199, 1761754199),
(46666, 'Jeremiah 16:2', 'Jeremiah', 16, 2, '”دلته وادۀ ونۀ کړې او نۀ زامن او لوڼه پېدا کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_2.mp3', '', 1761754199, 1761754199),
(46667, 'Jeremiah 16:3', 'Jeremiah', 16, 3, 'ځکه چې زۀ مالِک خُدائ دا وايم چې، کوم ماشومان چې دلته پېدا کيږى او هم داسې د هغوئ مور، پلار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_3.mp3', '', 1761754199, 1761754199),
(46668, 'Jeremiah 16:4', 'Jeremiah', 16, 4, 'چې هغوئ به د سختو بيمارو نه مړۀ شى. او په هغوئ به هيڅ څوک ژړا ونۀ کړى او نۀ به يې ښخ کړى، او د هغوئ لاشونه به په زمکه لکه د سوټو په شان خوارۀ وارۀ پراتۀ وى. او هغوئ به په جنګ او قحط مړۀ شى، او د هغوئ لاشونه به د ټپوسانو، او د ځنګلى ځناورو خوراک شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_4.mp3', '', 1761754199, 1761754199),
(46669, 'Jeremiah 16:5', 'Jeremiah', 16, 5, 'مالِک خُدائ داسې فرمائى چې، هغه کور ته مۀ ورننوځه په کوم کښې چې د مړى ژړا وى، د هغوئ سره ماتم او همدردى مۀ کوه، ځکه چې ما د هغه خلقو نه خپل برکت، مينه او رحم اخوا کړے دے، دا د مالِک خُدائ وينا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_5.mp3', '', 1761754199, 1761754199),
(46670, 'Jeremiah 16:6', 'Jeremiah', 16, 6, 'مالداره او غريبانان به دواړه په دې مُلک کښې مړۀ شى، هغوئ به نۀ ښخ کړے شى او نۀ به ورباندې ماتم وشى، د هغوئ دوستان به نۀ خپل ځانونه دردمند کړى او نۀ به د خفګان ښکاره کولو په وجه خپل سرونه د هغوئ دپاره ګنجى کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_6.mp3', '', 1761754199, 1761754199),
(46671, 'Jeremiah 16:7', 'Jeremiah', 16, 7, 'هيڅوک به هغوئ ته د غمرازۍ روټۍ نۀ راوړى، تر دې چې د خپل مور او پلار دپاره به تعزيت نۀ کوى، او نۀ به ورته څوک د تسلۍ دپاره څښلو له څۀ ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_7.mp3', '', 1761754199, 1761754199),
(46672, 'Jeremiah 16:8', 'Jeremiah', 16, 8, 'او هغه کور ته هم مۀ ورننوځه په کوم کور کښې چې د خوراک څښاک پروګرام وى او د هغوئ سره روټۍ ته مۀ کښېنه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_8.mp3', '', 1761754199, 1761754199),
(46673, 'Jeremiah 16:9', 'Jeremiah', 16, 9, 'ځکه چې دا مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ درته فرمائى، ستا په ژوند کښې او ستا د سترګو د وړاندې به زۀ په دې مُلک کښې د خندا او د خوشحالۍ آوازونه ختم کړم. نور به په کښې د ناوې او زلمى د خوشحالۍ آوازونه نۀ اورېدلے کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_9.mp3', '', 1761754199, 1761754199),
(46674, 'Jeremiah 16:10', 'Jeremiah', 16, 10, 'کله چې تۀ هغوئ ته دا هر څۀ ووائې نو هغوئ به درنه تپوس وکړى چې، مالِک خُدائ په مونږ دومره سخت افت ولې نازلوى؟ مونږ څۀ غلطى کړې ده؟ مونږ داسې کومه ګناه د مالِک خُدائ خلاف کړې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_10.mp3', '', 1761754199, 1761754199),
(46675, 'Jeremiah 16:11', 'Jeremiah', 16, 11, 'نو بيا هغوئ ته ووايه چې، مالِک خُدائ فرمائى چې، ستاسو پلار نيکۀ زۀ هېر کړے وم، هغوئ زما په ځائ د نورو معبودانو عبادت او خِدمت وکړو. او هغوئ زۀ پرېښودم او زما د کلام تابعدارى يې ونۀ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_11.mp3', '', 1761754199, 1761754199),
(46676, 'Jeremiah 16:12', 'Jeremiah', 16, 12, 'خو تاسو د خپل پلار نيکۀ نه هم زيات بد سلوک وکړو. ګوره چې څنګه تاسو هر يو زما د پيروى په ځائ د خپلو سرکشه او بدکاره زړونو خواهشاتو ته غوږ ونيولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_12.mp3', '', 1761754199, 1761754199),
(46677, 'Jeremiah 16:13', 'Jeremiah', 16, 13, 'نو زۀ به تاسو د دې مُلک نه داسې مُلک ته وشړم چې نۀ يې تاسو ته څۀ پته شته او نۀ يې ستاسو پلار نيکۀ ته څۀ پته وه، نو هلته به تاسو شپه او ورځ د نورو معبودانو عبادت کوئ، ځکه چې زۀ به په تاسو نور رحم نۀ کوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_13.mp3', '', 1761754199, 1761754199),
(46678, 'Jeremiah 16:14', 'Jeremiah', 16, 14, 'مالِک خُدائ وفرمائيل چې، ”داسې وخت راروان دے چې خلق به داسې قسم نۀ خورى چې، د ژوندى خُدائ پاک په نوم مې دې قسم وى چا چې بنى اِسرائيل د مِصر نه راوويستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_14.mp3', '', 1761754199, 1761754199),
(46679, 'Jeremiah 16:15', 'Jeremiah', 16, 15, 'خو هغوئ به داسې قسم خورى چې، د ژوندى خُدائ پاک په نوم مې دې قسم وى چا چې بنى اِسرائيل د شمال او د هغه ټولو مُلکونو نه راوويستل کومو ته چې هغۀ شړلى وُو. ځکه چې زۀ به هغوئ دوباره هغه مُلک ته واپس راولم کوم چې ما د هغوئ پلار نيکۀ له ورکړے وو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_15.mp3', '', 1761754199, 1761754199),
(46680, 'Jeremiah 16:16', 'Jeremiah', 16, 16, 'مالِک خُدائ فرمائى چې، ”بلکې زۀ به اوس ډېر ماهيګر درولېږم چې هغوئ به دوئ راونيسى. او د دې نه وروستو به زۀ ډېر ښکاريان درولېږم او دوئ به هغوئ په هر يو غر، غونډۍ او د ګټانو د غارونو نه ښکار کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_16.mp3', '', 1761754199, 1761754199),
(46681, 'Jeremiah 16:17', 'Jeremiah', 16, 17, 'د هغوئ ټول عملونه زما د سترګو د وړاندې دى او زۀ يې وينم، هغه زما نه پټ نۀ دى، او تر دې چې د هغوئ ګناهونه هم زما د سترګو نه پټ پناه نۀ دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_17.mp3', '', 1761754199, 1761754199),
(46682, 'Jeremiah 16:18', 'Jeremiah', 16, 18, 'زۀ به هغوئ له د خپلو ګناهونو او حرامو کارونو بدله يو په دوه ورکړم، ځکه چې هغوئ د بې‌ساه شکلونو او نفرت آميزه بُتانو په وجه زما موروثى مُلک پليت کړے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_18.mp3', '', 1761754199, 1761754199),
(46683, 'Jeremiah 16:19', 'Jeremiah', 16, 19, 'اے مالِکه خُدايه، تۀ زما طاقت او زما قلعه يې، د مصيبت په وخت کښې زما پناه ګاه يې. د دُنيا د آخر سر نه به قومونه تا ته راشى او وائى به چې، ”زمونږ پلار نيکۀ سره هيڅ نۀ وو بلکې دروغژن معبودان، هغه بې‌کاره بُتان چې دوئ ته هيڅ قسمه ښېګړه نۀ شى ورکولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_19.mp3', '', 1761754199, 1761754199),
(46684, 'Jeremiah 16:20', 'Jeremiah', 16, 20, 'خلق خو ځان له خپل خُدايان په خپله جوړوى، خو په حقيقت کښې هغه صحيح خُدايان نۀ وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_20.mp3', '', 1761754199, 1761754199),
(46685, 'Jeremiah 16:21', 'Jeremiah', 16, 21, '”نو په دې وجه به زۀ هغوئ ته په دې وخت کښې د خپل زور او طاقت په حقله تعليم ورکړم. نو بيا به هغوئ په دې باندې پوهه شى چې زما نوم مالِک خُدائ دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah16_verse_21.mp3', '', 1761754199, 1761754199),
(46686, 'Jeremiah 21:1', 'Jeremiah', 21, 1, 'هغه پېغام چې د مالِک خُدائ له خوا نه يرمياه ته ورکړے شو کله چې د يهوداه بادشاه صدقياه د مُلکياه زوئ فشحور او د معسياه زوئ صفنياه اِمام يرمياه ته د دې عرض سره ورولېږل چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_1.mp3', '', 1761754199, 1761754199),
(46687, 'Jeremiah 21:2', 'Jeremiah', 21, 2, '”زمونږ دپاره د مالِک خُدائ نه تپوس وکړه ځکه چې د بابل بادشاه نبوکدنضر او د هغۀ لښکر په مونږ حمله کوى، نو کېدے شى چې مالِک خُدائ زمونږ دپاره د وړاندې په شان معجزه وکړى او نبوکدنضر د دې ځائ نه په وتو مجبور کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_2.mp3', '', 1761754199, 1761754199),
(46688, 'Jeremiah 21:3', 'Jeremiah', 21, 3, 'بيا يرمياه جواب ورکړو، ”تاسو صدقياه بادشاه ته واپس لاړ شئ او ورته ووايئ چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_3.mp3', '', 1761754199, 1761754199),
(46689, 'Jeremiah 21:4', 'Jeremiah', 21, 4, 'مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک دا فرمائى چې، زۀ به ستاسو د جنګ وسله کومه چې ستاسو په لاس کښې ده بې‌کاره کړم او ستاسو خلاف به يې استعمال کړم، کومه چې تاسو د جنګ دپاره د بابل د بادشاه او د بابل د خلقو خلاف به استعمالوئ څوک چې د دېوال نه اخوا دى او په تاسو حمله کوى. نو په حقيقت کښې به زۀ ستاسو دشمنان د دې ښار زړۀ ته راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_4.mp3', '', 1761754199, 1761754199),
(46690, 'Jeremiah 21:5', 'Jeremiah', 21, 5, 'زۀ به په خپله خپل زورَور لاس دراوږد کړم او ستاسو خِلاف به په غصې، قهر، او لوئ غضب سره جنګ وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_5.mp3', '', 1761754199, 1761754199),
(46691, 'Jeremiah 21:6', 'Jeremiah', 21, 6, 'زۀ به په دې ښار سخته وبا رانازله کړم، زۀ به انسانان او ځناور دواړه مړۀ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_6.mp3', '', 1761754199, 1761754199),
(46692, 'Jeremiah 21:7', 'Jeremiah', 21, 7, 'مالِک خُدائ فرمائى چې د دې نه وروستو به زۀ صدقياه بادشاه او د هغۀ ټول آفسران او د هغۀ نور خلق کوم چې دې ښار کښې اوسيږى او د وبا، جنګ، او قحط نه ژوندى پاتې شوى وى زۀ به هغوئ نبوکدنضر بادشاه ته او د هغوئ دشمن ته حواله کړم څوک چې د هغوئ ژوند ختمولو پسې ګرځى. هغه به هغوئ په تُوره په بې‌دردۍ سره مړۀ کړى، او په دوئ باندې به هيڅ قسمه رحم، مينه او نۀ به پرې څۀ زړۀ سواندے ښکاره کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_7.mp3', '', 1761754199, 1761754199),
(46693, 'Jeremiah 21:8', 'Jeremiah', 21, 8, 'بيا مالِک خُدائ ما ته وفرمائيل چې دې خلقو ته ووايه چې، ”زۀ، مالِک خُدائ ستاسو په وړاندې دوه لارې پېش کوم چې يوه د ژوند او بله د مرګ لاره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_8.mp3', '', 1761754199, 1761754199),
(46694, 'Jeremiah 21:9', 'Jeremiah', 21, 9, 'هر څوک هم چې په دې ښار کښې پاتې شى نو هغه به په جنګ، قحط او يا د وبا په وجه مړۀ شى. خو هر څوک چې بهر ووځى او خپل ځان بابليانو ته حواله کړى چا چې ښار محاصره کړے دے هغوئ به ژوندى پاتې شى، او هغوئ ته به د ژوندون غنيمت ورکړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_9.mp3', '', 1761754199, 1761754199),
(46695, 'Jeremiah 21:10', 'Jeremiah', 21, 10, 'مالِک خُدائ فرمائى چې، ما دا فېصله کړې ده چې زۀ به دا ښار بچ نۀ کړم او افتونه به پرې نازل کړم، نه چې آبادى. دا به د بابل بادشاه ته حواله کړم او هغه به دا ښار په اور تباه کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_10.mp3', '', 1761754199, 1761754199),
(46696, 'Jeremiah 21:11', 'Jeremiah', 21, 11, '‏ ”د يهوداه شاهى خاندان ته ووايه، د مالِک خُدائ پېغام واورئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_11.mp3', '', 1761754199, 1761754199),
(46697, 'Jeremiah 21:12', 'Jeremiah', 21, 12, 'اے د داؤد خاندانه، مالِک خُدائ تاسو ته داسې فرمائى، هر سحر د خلقو اِنصاف کوئ د چا نه چې غلا شوې وى او هغوئ ته د ظالمانو د لاس نه خلاصون ورکوئ، ګنې زما غضب به رانازل شى او هر څۀ به لکه د اور په شان وسوزوى او دا به ستاسو د هغه شرارت په وجه داسې بليږى چې هيڅ څوک به يې نۀ شى مړ کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_12.mp3', '', 1761754199, 1761754199),
(46698, 'Jeremiah 21:13', 'Jeremiah', 21, 13, 'مالِک خُدائ فرمائى، اے يروشلمه، زۀ به په ذاتى توګه ستاسو خلاف جنګ کوم، تاسو څوک چې په دې وادۍ بره اوسېږئ او په اوچت ګټ پراتۀ يئ، تاسو څوک چې په ډېر فخر سره وايئ، دلته څوک زمونږ خلاف راتلے شى څۀ؟ او زمونږ پناه ګاه ته څوک راننوتلے شى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_13.mp3', '', 1761754199, 1761754199),
(46699, 'Jeremiah 21:14', 'Jeremiah', 21, 14, 'مالِک خُدائ فرمائى چې، زۀ به ستاسو د عمل په مطابق چې د څومره سزا قابل يئ هومره درکړم. زۀ به ستا د قلعه ګانو د لرګو په ستنو اور بل کړم او د هغې نه ګېرچاپېره چې هر څۀ وى هغه به وسوزوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah21_verse_14.mp3', '', 1761754199, 1761754199),
(46700, 'Judges 9:1', 'Judges', 9, 1, 'یوه ورځ د جدعون زوی ابیملک خپلو ماما ګانو ته چې په شکیم کې وو ورغی، هغوی او د خپلې مور ټولې طایفې ته یې وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_1.mp3', '', 1761754199, 1761754199),
(46701, 'Judges 9:2', 'Judges', 9, 2, '«د شکیم د ټولو سړیو څخه پوښتنه وکړئ چې تاسو ته کومه یوه لاره ښه ده؟ چې اویا تنه یعنې د جدعون ټول زامن په تاسو باندې پاچاهي وکړي او که یوازې یو کس؟ په یاد ساتئ، ابیملک ستاسو خپل هډوکی او خپله وینه ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_2.mp3', '', 1761754199, 1761754199),
(46702, 'Judges 9:3', 'Judges', 9, 3, 'کله چې د هغه ماماګانو دا ټولې خبرې د شکیم خلکو ته وکړې، نو هغوی پرېکړه وکړه چې د ابیملک څخه پیروي وکړي، ځکه چې هغه یې خپلوان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_3.mp3', '', 1761754199, 1761754199),
(46703, 'Judges 9:4', 'Judges', 9, 4, 'هغوی هغه ته د بعل بریت د بتخانې څخه اویا د سپینو زرو سکې ورکړلې او په هغو باندې یې لنډغران اجیر ونیول چې د هغه سره یوځای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_4.mp3', '', 1761754199, 1761754199),
(46704, 'Judges 9:5', 'Judges', 9, 5, 'هغه د خپل پلار کور ته چې په عفره کې ؤ، لاړ او د یوې تیږې په سر باندې یې خپل اویا ناسکه ورونه ووژل. خو یوتام چې د جدعون کشر زوی ؤ ځان ورڅخه پټ کړ او ژوندی پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_5.mp3', '', 1761754199, 1761754199),
(46705, 'Judges 9:6', 'Judges', 9, 6, 'بیا د شکیم او بیت ملو ټول سړي سره راټول شول او د څېړۍ سپېڅلې ونې ته چې په شکیم کې وه، ورغلل او ابیملک یې پاچا کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_6.mp3', '', 1761754199, 1761754199),
(46706, 'Judges 9:7', 'Judges', 9, 7, 'کله چې یوتام د دې څخه خبر شو، هغه د جرزیم د غره سرته وخوت او هغوی ته یې چیغې کړې: «د شکیم خلکو ماته غوږ ونیسئ، نو خدای به تاسو ته غوږ ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_7.mp3', '', 1761754199, 1761754199),
(46707, 'Judges 9:8', 'Judges', 9, 8, 'یو وخت ونې سره راټولې شولې چې د ځانونو دپاره یو پاچا وټاکي. هغوی د زیتون ونې ته وویل: ‹ته زمونږ پاچا شه.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_8.mp3', '', 1761754199, 1761754199),
(46708, 'Judges 9:9', 'Judges', 9, 9, 'خو د زیتون ونې په ځواب کې وویل: ‹ایا زه په تاسو باندې د پاچاهي کولو په خاطر د خپلو تېلو د تولیدولو څخه چې د خدایانو او انسانانو د درناوي دپاره ورڅخه کار اخیستل کیږي، لاس واخلم؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_9.mp3', '', 1761754199, 1761754199),
(46709, 'Judges 9:10', 'Judges', 9, 10, 'بیا ونو د انځر ونې ته وویل: ‹ته زمونږ پاچا شه.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_10.mp3', '', 1761754199, 1761754199),
(46710, 'Judges 9:11', 'Judges', 9, 11, 'خو د انځر ونې په ځواب کې وویل: ‹ایا زه په تاسو باندې د پاچاهي کولو په خاطر د خپلې ښې او خوږې مېوې د تولیدولو څخه لاس واخلم؟›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges9_verse_11.mp3', '', 1761754199, 1761754199);